"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[89007],{36247(e,o,s){s.r(o),s.d(o,{assets:()=>i,contentTitle:()=>c,default:()=>l,frontMatter:()=>t,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"cursos/react/modulos/custom-hooks/cuestionario","title":"Cuestionario M10 \u2014 Custom Hooks","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/react/modulos/10-custom-hooks/cuestionario.md","sourceDirName":"cursos/react/modulos/10-custom-hooks","slug":"/cursos/react/modulos/custom-hooks/cuestionario","permalink":"/sasf-temarios/cursos/react/modulos/custom-hooks/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/react/modulos/custom-hooks/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/react/modulos/custom-hooks/ejercicio"}}');var n=s(74848),r=s(28453);const t={sidebar_label:"Cuestionario"},c="Cuestionario M10 \u2014 Custom Hooks",i={},d=[{value:"1. [Investigar] Investig\xe1 la filosof\xeda de &quot;TanStack Hooks&quot; y c\xf3mo Tanner Linsley dise\xf1a hooks reutilizables y agn\xf3sticos de framework (React, Vue, Solid). \xbfQu\xe9 patrones de sus librer\xedas (React Query, TanStack Table, TanStack Router) podr\xedas aplicar al dise\xf1ar tus propios custom hooks?",id:"1-investigar-investig\xe1-la-filosof\xeda-de-tanstack-hooks-y-c\xf3mo-tanner-linsley-dise\xf1a-hooks-reutilizables-y-agn\xf3sticos-de-framework-react-vue-solid-qu\xe9-patrones-de-sus-librer\xedas-react-query-tanstack-table-tanstack-router-podr\xedas-aplicar-al-dise\xf1ar-tus-propios-custom-hooks",level:3},{value:"2. [Investigar] \xbfQu\xe9 es <code>usehooks-ts</code> y qu\xe9 hooks ofrece que van m\xe1s all\xe1 de los b\xe1sicos (<code>useDebounce</code>, <code>useLocalStorage</code>)? Investig\xe1 hooks como <code>useEventListener</code>, <code>useIntersectionObserver</code>, <code>useIsFirstRender</code>, <code>useStep</code>, y <code>useCounter</code>. \xbfQu\xe9 patrones de implementaci\xf3n segu\xeds viendo?",id:"2-investigar-qu\xe9-es-usehooks-ts-y-qu\xe9-hooks-ofrece-que-van-m\xe1s-all\xe1-de-los-b\xe1sicos-usedebounce-uselocalstorage-investig\xe1-hooks-como-useeventlistener-useintersectionobserver-useisfirstrender-usestep-y-usecounter-qu\xe9-patrones-de-implementaci\xf3n-segu\xeds-viendo",level:3},{value:"3. [Investigar] \xbfQu\xe9 es el patr\xf3n &quot;Hook + Context&quot; vs &quot;Hook + Zustand&quot; para custom hooks como <code>useAuth</code>? La clase define <code>useAuth</code> como wrapper de <code>useContext(AuthContext)</code>. \xbfQu\xe9 cambiar\xeda si migraras a Zustand y c\xf3mo afecta el dise\xf1o de tus custom hooks?",id:"3-investigar-qu\xe9-es-el-patr\xf3n-hook--context-vs-hook--zustand-para-custom-hooks-como-useauth-la-clase-define-useauth-como-wrapper-de-usecontextauthcontext-qu\xe9-cambiar\xeda-si-migraras-a-zustand-y-c\xf3mo-afecta-el-dise\xf1o-de-tus-custom-hooks",level:3},{value:"4. [Investigar] \xbfQu\xe9 son los &quot;hooks factory&quot; y c\xf3mo se diferencian de los custom hooks? Investig\xe1 el patr\xf3n <code>create</code> de Zustand y c\xf3mo retorna tanto un hook como m\xe9todos externos (<code>getState</code>, <code>subscribe</code>, <code>setState</code>). \xbfC\xf3mo dise\xf1ar\xedas una factory de hooks para un servicio de API?",id:"4-investigar-qu\xe9-son-los-hooks-factory-y-c\xf3mo-se-diferencian-de-los-custom-hooks-investig\xe1-el-patr\xf3n-create-de-zustand-y-c\xf3mo-retorna-tanto-un-hook-como-m\xe9todos-externos-getstate-subscribe-setstate-c\xf3mo-dise\xf1ar\xedas-una-factory-de-hooks-para-un-servicio-de-api",level:3},{value:"5. [Conectar] La clase implementa <code>useDebounce</code> y <code>useLocalStorage</code>. Conect\xe1 estos hooks con el concepto de &quot;useSyncExternalStore&quot; \u2014 \xbfc\xf3mo implementar\xedas un <code>useLocalStorage</code> que use <code>useSyncExternalStore</code> para reaccionar a cambios en localStorage desde otras pesta\xf1as (evento <code>storage</code>)?",id:"5-conectar-la-clase-implementa-usedebounce-y-uselocalstorage-conect\xe1-estos-hooks-con-el-concepto-de-usesyncexternalstore--c\xf3mo-implementar\xedas-un-uselocalstorage-que-use-usesyncexternalstore-para-reaccionar-a-cambios-en-localstorage-desde-otras-pesta\xf1as-evento-storage",level:3},{value:"6. [Conectar] La clase muestra hooks de ejemplo (<code>useAuth</code>, <code>useTasks</code>, <code>useDebounce</code>, <code>useLocalStorage</code>, <code>useMediaQuery</code>). Investig\xe1 c\xf3mo har\xedas un hook <code>useMediaQuery</code> que use <code>matchMedia</code> con <code>useSyncExternalStore</code> en lugar de <code>useEffect</code> + <code>useState</code>. \xbfQu\xe9 ventaja da?",id:"6-conectar-la-clase-muestra-hooks-de-ejemplo-useauth-usetasks-usedebounce-uselocalstorage-usemediaquery-investig\xe1-c\xf3mo-har\xedas-un-hook-usemediaquery-que-use-matchmedia-con-usesyncexternalstore-en-lugar-de-useeffect--usestate-qu\xe9-ventaja-da",level:3},{value:"7. [Conectar] La clase organiza hooks en <code>hooks/</code> separados de los contexts. Investig\xe1 el patr\xf3n de &quot;barrel exports&quot; (index.ts) para hooks y c\xf3mo afecta el tree-shaking. \xbfQu\xe9 ventaja tiene <code>import &amp;#x7B; useAuth &amp;#x7D; from &#39;@/hooks&#39;</code> vs <code>import &amp;#x7B; useAuth &amp;#x7D; from &#39;@/hooks/useAuth&#39;</code>?",id:"7-conectar-la-clase-organiza-hooks-en-hooks-separados-de-los-contexts-investig\xe1-el-patr\xf3n-de-barrel-exports-indexts-para-hooks-y-c\xf3mo-afecta-el-tree-shaking-qu\xe9-ventaja-tiene-import-x7b-useauth-x7d-from-hooks-vs-import-x7b-useauth-x7d-from-hooksuseauth",level:3},{value:"8. [Cuestionar] \xbfCu\xe1ndo un custom hook es &quot;demasiado&quot; abstracto? La comunidad debate si hooks como <code>useWindowSize</code>, <code>useIsMounted</code>, <code>usePrevious</code> son genuinamente \xfatiles o sobre-ingenier\xeda (1-3 l\xedneas de c\xf3digo propio vs una abstracci\xf3n). \xbfD\xf3nde est\xe1 la l\xednea entre &quot;hook \xfatil&quot; y &quot;hook innecesario&quot;?",id:"8-cuestionar-cu\xe1ndo-un-custom-hook-es-demasiado-abstracto-la-comunidad-debate-si-hooks-como-usewindowsize-useismounted-useprevious-son-genuinamente-\xfatiles-o-sobre-ingenier\xeda-1-3-l\xedneas-de-c\xf3digo-propio-vs-una-abstracci\xf3n-d\xf3nde-est\xe1-la-l\xednea-entre-hook-\xfatil-y-hook-innecesario",level:3},{value:"9. [Cuestionar] \xbfEs &quot;hooks for everything&quot; una buena arquitectura? Algunos desarrolladores crean hooks para TODO (useFormValidation, useTaskFiltering, useTaskSorting), fragmentando la l\xf3gica en decenas de hooks. \xbfCu\xe1ndo un custom hook crea m\xe1s problemas que los que resuelve (prop drilling de hooks, acoplamiento oculto)?",id:"9-cuestionar-es-hooks-for-everything-una-buena-arquitectura-algunos-desarrolladores-crean-hooks-para-todo-useformvalidation-usetaskfiltering-usetasksorting-fragmentando-la-l\xf3gica-en-decenas-de-hooks-cu\xe1ndo-un-custom-hook-crea-m\xe1s-problemas-que-los-que-resuelve-prop-drilling-de-hooks-acoplamiento-oculto",level:3},{value:"10. [Cuestionar] La clase usa <code>useEffect</code> dentro de <code>useDebounce</code>. \xbfEs esto correcto o deber\xeda usar <code>useLayoutEffect</code>? La comunidad debate cu\xe1ndo usar <code>useEffect</code> vs <code>useLayoutEffect</code>, especialmente en hooks de UI como debounce, media queries, y resize observers. \xbfQu\xe9 dice el equipo de React?",id:"10-cuestionar-la-clase-usa-useeffect-dentro-de-usedebounce-es-esto-correcto-o-deber\xeda-usar-uselayouteffect-la-comunidad-debate-cu\xe1ndo-usar-useeffect-vs-uselayouteffect-especialmente-en-hooks-de-ui-como-debounce-media-queries-y-resize-observers-qu\xe9-dice-el-equipo-de-react",level:3}];function u(e){const o={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(o.header,{children:(0,n.jsx)(o.h1,{id:"cuestionario-m10--custom-hooks",children:"Cuestionario M10 \u2014 Custom Hooks"})}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,n.jsx)(o.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"1-investigar-investig\xe1-la-filosof\xeda-de-tanstack-hooks-y-c\xf3mo-tanner-linsley-dise\xf1a-hooks-reutilizables-y-agn\xf3sticos-de-framework-react-vue-solid-qu\xe9-patrones-de-sus-librer\xedas-react-query-tanstack-table-tanstack-router-podr\xedas-aplicar-al-dise\xf1ar-tus-propios-custom-hooks",children:'1. [Investigar] Investig\xe1 la filosof\xeda de "TanStack Hooks" y c\xf3mo Tanner Linsley dise\xf1a hooks reutilizables y agn\xf3sticos de framework (React, Vue, Solid). \xbfQu\xe9 patrones de sus librer\xedas (React Query, TanStack Table, TanStack Router) podr\xedas aplicar al dise\xf1ar tus propios custom hooks?'}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),': Tanner Linsley sigue principios clave en sus hooks: (1) "Headless UI": el hook no renderiza nada, solo maneja estado y l\xf3gica (el desarrollador controla el render), (2) "Framework-agnostic core": la l\xf3gica central vive en un paquete independiente (ej: ',(0,n.jsx)(o.code,{children:"@tanstack/query-core"}),") y el adaptador de React (",(0,n.jsx)(o.code,{children:"@tanstack/react-query"}),') solo conecta con hooks, (3) "Get, not Set": los hooks exponen datos derivados y funciones de acci\xf3n, no setters directos, (4) "TypeScript-first": tipos inferidos autom\xe1ticamente, sin necesidad de gen\xe9ricos manuales, (5) "Composable": hooks peque\xf1os que se componen (ej: ',(0,n.jsx)(o.code,{children:"useReactTable"})," usa ",(0,n.jsx)(o.code,{children:"useState"}),", ",(0,n.jsx)(o.code,{children:"useReducer"}),", ",(0,n.jsx)(o.code,{children:"useMemo"}),", etc.)."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Estos patrones producen hooks que son f\xe1ciles de usar, dif\xedciles de usar mal, y portables entre proyectos. Para aplicar en tus custom hooks: (1) separ\xe1 la l\xf3gica de la UI (tu hook no deber\xeda retornar JSX), (2) us\xe1 gen\xe9ricos para type safety (",(0,n.jsx)(o.code,{children:"useDebounce&#x3C;T>"}),"), (3) expon\xe9 estados claros (no booleanos aislados \u2014 us\xe1 discriminated unions como ",(0,n.jsx)(o.code,{children:"&#x7B; status: 'loading' &#x7D; | &#x7B; status: 'success', data: T &#x7D;"}),'), (4) hac\xe9 que el hook sea "just works" con defaults razonables pero configurable. Fuente: "How to build a React hook" en el blog de Tanner Linsley, el c\xf3digo fuente de ',(0,n.jsx)(o.code,{children:"@tanstack/react-query"}),', y la charla "Headless UI Components" en React Summit.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"2-investigar-qu\xe9-es-usehooks-ts-y-qu\xe9-hooks-ofrece-que-van-m\xe1s-all\xe1-de-los-b\xe1sicos-usedebounce-uselocalstorage-investig\xe1-hooks-como-useeventlistener-useintersectionobserver-useisfirstrender-usestep-y-usecounter-qu\xe9-patrones-de-implementaci\xf3n-segu\xeds-viendo",children:["2. [Investigar] \xbfQu\xe9 es ",(0,n.jsx)(o.code,{children:"usehooks-ts"})," y qu\xe9 hooks ofrece que van m\xe1s all\xe1 de los b\xe1sicos (",(0,n.jsx)(o.code,{children:"useDebounce"}),", ",(0,n.jsx)(o.code,{children:"useLocalStorage"}),")? Investig\xe1 hooks como ",(0,n.jsx)(o.code,{children:"useEventListener"}),", ",(0,n.jsx)(o.code,{children:"useIntersectionObserver"}),", ",(0,n.jsx)(o.code,{children:"useIsFirstRender"}),", ",(0,n.jsx)(o.code,{children:"useStep"}),", y ",(0,n.jsx)(o.code,{children:"useCounter"}),". \xbfQu\xe9 patrones de implementaci\xf3n segu\xeds viendo?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": ",(0,n.jsx)(o.code,{children:"usehooks-ts"})," es una colecci\xf3n de custom hooks TypeScript mantenida por Julien Carpon. Incluye hooks que encapsulan APIs web nativas: ",(0,n.jsx)(o.code,{children:"useEventListener(event, handler, element)"})," abstrae ",(0,n.jsx)(o.code,{children:"addEventListener"}),"/",(0,n.jsx)(o.code,{children:"removeEventListener"})," con cleanup autom\xe1tico; ",(0,n.jsx)(o.code,{children:"useIntersectionObserver(ref, options)"})," devuelve ",(0,n.jsx)(o.code,{children:"entry"})," con ",(0,n.jsx)(o.code,{children:"isIntersecting"}),", ",(0,n.jsx)(o.code,{children:"intersectionRatio"}),"; ",(0,n.jsx)(o.code,{children:"useStep(max)"})," maneja navegaci\xf3n paso a paso con ",(0,n.jsx)(o.code,{children:"next"}),", ",(0,n.jsx)(o.code,{children:"prev"}),", ",(0,n.jsx)(o.code,{children:"goTo"}),"; ",(0,n.jsx)(o.code,{children:"useIsFirstRender()"})," retorna ",(0,n.jsx)(o.code,{children:"true"})," solo en el primer render; ",(0,n.jsx)(o.code,{children:"useCounter(initialValue)"})," ofrece ",(0,n.jsx)(o.code,{children:"count"}),", ",(0,n.jsx)(o.code,{children:"increment"}),", ",(0,n.jsx)(o.code,{children:"decrement"}),", ",(0,n.jsx)(o.code,{children:"reset"}),", ",(0,n.jsx)(o.code,{children:"setCount"}),"."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Los patrones comunes que emergen: (1) encapsulan APIs del navegador con ",(0,n.jsx)(o.code,{children:"useEffect"})," + cleanup, (2) usan ",(0,n.jsx)(o.code,{children:"useRef"})," para valores que no deben causar re-renders, (3) exponen tanto el valor como funciones de control, (4) soportan gen\xe9ricos para type safety, (5) usan lazy initialization (",(0,n.jsx)(o.code,{children:"useState(() => ...)"}),') para valores iniciales costosos. Estos hooks son excelentes ejemplos de "extraer l\xf3gica repetitiva" \u2014 cada uno encapsula un patr\xf3n com\xfan que de otra manera copiar\xedas entre componentes. Fuente: usehooks-ts.com, el repo github.com/juliencrn/usehooks-ts, y la documentaci\xf3n de cada hook.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"3-investigar-qu\xe9-es-el-patr\xf3n-hook--context-vs-hook--zustand-para-custom-hooks-como-useauth-la-clase-define-useauth-como-wrapper-de-usecontextauthcontext-qu\xe9-cambiar\xeda-si-migraras-a-zustand-y-c\xf3mo-afecta-el-dise\xf1o-de-tus-custom-hooks",children:['3. [Investigar] \xbfQu\xe9 es el patr\xf3n "Hook + Context" vs "Hook + Zustand" para custom hooks como ',(0,n.jsx)(o.code,{children:"useAuth"}),"? La clase define ",(0,n.jsx)(o.code,{children:"useAuth"})," como wrapper de ",(0,n.jsx)(o.code,{children:"useContext(AuthContext)"}),". \xbfQu\xe9 cambiar\xeda si migraras a Zustand y c\xf3mo afecta el dise\xf1o de tus custom hooks?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Con Context, ",(0,n.jsx)(o.code,{children:"useAuth"})," es un wrapper que accede al contexto y valida que existe:"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"function useAuth() {\r\n  const ctx = useContext(AuthContext)\r\n  if (!ctx) throw new Error('useAuth must be within AuthProvider')\r\n  return ctx\r\n}\n"})}),"\n",(0,n.jsxs)(o.p,{children:["Con Zustand, ",(0,n.jsx)(o.code,{children:"useAuth"})," se convierte en selectores directos al store (no necesita Provider ni validaci\xf3n):"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"const useAuthStore = create<AuthStore>(...)\r\nfunction useAuth() {\r\n  return useAuthStore(state => ({ user: state.user, login: state.login, logout: state.logout }))\r\n}\n"})}),"\n",(0,n.jsxs)(o.p,{children:["Esto cambia el dise\xf1o: (1) no hay Provider \u2014 el hook funciona en cualquier parte, (2) los selectores permiten granularidad (",(0,n.jsx)(o.code,{children:"useAuthStore(s => s.user)"})," solo se re-renderiza cuando user cambia), (3) pod\xe9s acceder al estado fuera de React (",(0,n.jsx)(o.code,{children:"useAuthStore.getState().token"})," en interceptors)."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),': La migraci\xf3n a Zustand simplifica los custom hooks porque elimina la capa de Context (Provider + validaci\xf3n). Adem\xe1s, habilita selectores finos que ser\xedan complejos con Context (requieren splitting). El patr\xf3n emerge: el custom hook se convierte en una capa de "selectores y acciones convenientes" sobre el store, en lugar de un wrapper de Context. Daishi Kato describe esto como "el hook es la API p\xfablica, el store es el detalle de implementaci\xf3n". Fuente: Zustand docs, "From Context to Zustand" en el blog de Daishi Kato, y el c\xf3digo de TaskFlow en m\xf3dulo 17.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"4-investigar-qu\xe9-son-los-hooks-factory-y-c\xf3mo-se-diferencian-de-los-custom-hooks-investig\xe1-el-patr\xf3n-create-de-zustand-y-c\xf3mo-retorna-tanto-un-hook-como-m\xe9todos-externos-getstate-subscribe-setstate-c\xf3mo-dise\xf1ar\xedas-una-factory-de-hooks-para-un-servicio-de-api",children:['4. [Investigar] \xbfQu\xe9 son los "hooks factory" y c\xf3mo se diferencian de los custom hooks? Investig\xe1 el patr\xf3n ',(0,n.jsx)(o.code,{children:"create"})," de Zustand y c\xf3mo retorna tanto un hook como m\xe9todos externos (",(0,n.jsx)(o.code,{children:"getState"}),", ",(0,n.jsx)(o.code,{children:"subscribe"}),", ",(0,n.jsx)(o.code,{children:"setState"}),"). \xbfC\xf3mo dise\xf1ar\xedas una factory de hooks para un servicio de API?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),': Un "hook factory" es una funci\xf3n que crea un hook (y posiblemente otros artefactos) configurado con opciones espec\xedficas. Zustand ',(0,n.jsx)(o.code,{children:"create()"})," es el ejemplo can\xf3nico: retorna ",(0,n.jsx)(o.code,{children:"useStore"})," (hook) pero tambi\xe9n expone ",(0,n.jsx)(o.code,{children:"useStore.getState()"}),", ",(0,n.jsx)(o.code,{children:"useStore.setState()"}),", ",(0,n.jsx)(o.code,{children:"useStore.subscribe()"}),". Para un servicio de API, una factory podr\xeda ser:"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"function createApiHook<T>(endpoint: string) {\r\n  const useApi = () => {\r\n    const [state, setState] = useState<AsyncState<T>>({ status: 'idle' })\r\n    // ... fetching logic\r\n    return state\r\n  }\r\n  useApi.invalidate = () => queryClient.invalidateQueries({ queryKey: [endpoint] })\r\n  useApi.prefetch = () => queryClient.prefetchQuery({ queryKey: [endpoint], queryFn: ... })\r\n  return useApi\r\n}\r\nconst useTasks = createApiHook<Task[]>('/tasks')\r\nuseTasks.prefetch() // disponible fuera de React\n"})}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Este patr\xf3n es poderoso porque el hook no es solo una funci\xf3n \u2014 es un objeto con m\xe9todos y propiedades. Esto permite que la misma API sirva para uso dentro de React (el hook) y fuera de React (los m\xe9todos est\xe1ticos). Tanner Linsley usa este patr\xf3n extensivamente en TanStack: ",(0,n.jsx)(o.code,{children:"useQueryClient()"})," retorna un objeto con ",(0,n.jsx)(o.code,{children:"invalidateQueries"}),", ",(0,n.jsx)(o.code,{children:"prefetchQuery"}),", etc. Para TaskFlow, aplicar esto har\xeda los hooks m\xe1s modulares y testeables. Fuente: C\xf3digo fuente de Zustand ",(0,n.jsx)(o.code,{children:"create()"}),', "Hook Factory Pattern" en el blog de Tanner Linsley, y ejemplos en TanStack Query.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"5-conectar-la-clase-implementa-usedebounce-y-uselocalstorage-conect\xe1-estos-hooks-con-el-concepto-de-usesyncexternalstore--c\xf3mo-implementar\xedas-un-uselocalstorage-que-use-usesyncexternalstore-para-reaccionar-a-cambios-en-localstorage-desde-otras-pesta\xf1as-evento-storage",children:["5. [Conectar] La clase implementa ",(0,n.jsx)(o.code,{children:"useDebounce"})," y ",(0,n.jsx)(o.code,{children:"useLocalStorage"}),'. Conect\xe1 estos hooks con el concepto de "useSyncExternalStore" \u2014 \xbfc\xf3mo implementar\xedas un ',(0,n.jsx)(o.code,{children:"useLocalStorage"})," que use ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"})," para reaccionar a cambios en localStorage desde otras pesta\xf1as (evento ",(0,n.jsx)(o.code,{children:"storage"}),")?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"})," es ideal para ",(0,n.jsx)(o.code,{children:"useLocalStorage"})," porque ",(0,n.jsx)(o.code,{children:"localStorage"})," es un store externo (fuera de React) que puede cambiar por eventos de otras pesta\xf1as. La implementaci\xf3n:"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"function useLocalStorage<T>(key: string, initialValue: T) {\r\n  const getSnapshot = () => {\r\n    const item = localStorage.getItem(key)\r\n    return item ? (JSON.parse(item) as T) : initialValue\r\n  }\r\n\r\n  const subscribe = (callback: () => void) => {\r\n    const handler = (e: StorageEvent) => {\r\n      if (e.key === key && e.storageArea === localStorage) callback()\r\n    }\r\n    window.addEventListener('storage', handler)\r\n    return () => window.removeEventListener('storage', handler)\r\n  }\r\n\r\n  const value = useSyncExternalStore(subscribe, getSnapshot)\r\n\r\n  const setValue = (newValue: T | ((prev: T) => T)) => {\r\n    const next = typeof newValue === 'function' ? (newValue as Function)(getSnapshot()) : newValue\r\n    localStorage.setItem(key, JSON.stringify(next))\r\n    window.dispatchEvent(new StorageEvent('storage', { key, newValue: JSON.stringify(next), storageArea: localStorage }))\r\n  }\r\n\r\n  return [value, setValue] as const\r\n}\n"})}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"})," resuelve dos problemas: (1) consistencia en Concurrent Mode (todos los componentes que usan el mismo localStorage ven el mismo valor), (2) reactividad cross-tab (el evento ",(0,n.jsx)(o.code,{children:"storage"})," dispara ",(0,n.jsx)(o.code,{children:"callback"}),", React re-renderiza). La l\xednea ",(0,n.jsx)(o.code,{children:"window.dispatchEvent(new StorageEvent(...))"})," es necesaria porque el evento ",(0,n.jsx)(o.code,{children:"storage"})," nativo NO se dispara en la pesta\xf1a que HIZO el cambio (solo en otras pesta\xf1as). Para que ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"}),' detecte cambios locales, despachamos manualmente. Fuente: React docs "useSyncExternalStore", "Syncing localStorage across tabs" en el blog de Jake Archibald, y "useSyncExternalStore with localStorage" en ejemplos de react.dev.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"6-conectar-la-clase-muestra-hooks-de-ejemplo-useauth-usetasks-usedebounce-uselocalstorage-usemediaquery-investig\xe1-c\xf3mo-har\xedas-un-hook-usemediaquery-que-use-matchmedia-con-usesyncexternalstore-en-lugar-de-useeffect--usestate-qu\xe9-ventaja-da",children:["6. [Conectar] La clase muestra hooks de ejemplo (",(0,n.jsx)(o.code,{children:"useAuth"}),", ",(0,n.jsx)(o.code,{children:"useTasks"}),", ",(0,n.jsx)(o.code,{children:"useDebounce"}),", ",(0,n.jsx)(o.code,{children:"useLocalStorage"}),", ",(0,n.jsx)(o.code,{children:"useMediaQuery"}),"). Investig\xe1 c\xf3mo har\xedas un hook ",(0,n.jsx)(o.code,{children:"useMediaQuery"})," que use ",(0,n.jsx)(o.code,{children:"matchMedia"})," con ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"})," en lugar de ",(0,n.jsx)(o.code,{children:"useEffect"})," + ",(0,n.jsx)(o.code,{children:"useState"}),". \xbfQu\xe9 ventaja da?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": ",(0,n.jsx)(o.code,{children:"useMediaQuery"})," con ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"}),":"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"function useMediaQuery(query: string): boolean {\r\n  const getSnapshot = () => window.matchMedia(query).matches\r\n  const subscribe = (callback: () => void) => {\r\n    const mql = window.matchMedia(query)\r\n    mql.addEventListener('change', callback)\r\n    return () => mql.removeEventListener('change', callback)\r\n  }\r\n  return useSyncExternalStore(subscribe, getSnapshot)\r\n}\n"})}),"\n",(0,n.jsxs)(o.p,{children:["Ventajas sobre ",(0,n.jsx)(o.code,{children:"useEffect"})," + ",(0,n.jsx)(o.code,{children:"useState"}),": (1) sin render intermedio sin suscripci\xf3n (el estado se lee sincr\xf3nicamente en el render), (2) consistencia en Concurrent Mode (evita tearing si m\xfaltiples componentes leen el mismo media query), (3) no necesita ",(0,n.jsx)(o.code,{children:"useEffect"})," \u2014 el valor se obtiene directamente en el render, eliminando el delay de un frame entre cambio y actualizaci\xf3n de estado."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Con ",(0,n.jsx)(o.code,{children:"useEffect"})," + ",(0,n.jsx)(o.code,{children:"useState"}),", cuando el media query cambia, React: (1) recibe el evento, (2) llama a ",(0,n.jsx)(o.code,{children:"setState"}),", (3) programa re-render, (4) renderiza con el nuevo valor. Esto toma al menos 1 frame. Con ",(0,n.jsx)(o.code,{children:"useSyncExternalStore"}),', React lee el valor sincr\xf3nicamente durante el render, por lo que el cambio se refleja inmediatamente. Adem\xe1s, en Concurrent Mode, React puede "bloquear" el store externo para que todos los componentes vean el mismo valor consistente durante un render. Esta es la implementaci\xf3n recomendada en React 18+ para cualquier suscripci\xf3n a fuente externa. Fuente: React docs "useSyncExternalStore", "Why useSyncExternalStore matters" por Dan Abramov, y el ejemplo de media query en react.dev.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"7-conectar-la-clase-organiza-hooks-en-hooks-separados-de-los-contexts-investig\xe1-el-patr\xf3n-de-barrel-exports-indexts-para-hooks-y-c\xf3mo-afecta-el-tree-shaking-qu\xe9-ventaja-tiene-import-x7b-useauth-x7d-from-hooks-vs-import-x7b-useauth-x7d-from-hooksuseauth",children:["7. [Conectar] La clase organiza hooks en ",(0,n.jsx)(o.code,{children:"hooks/"}),' separados de los contexts. Investig\xe1 el patr\xf3n de "barrel exports" (index.ts) para hooks y c\xf3mo afecta el tree-shaking. \xbfQu\xe9 ventaja tiene ',(0,n.jsx)(o.code,{children:"import &#x7B; useAuth &#x7D; from '@/hooks'"})," vs ",(0,n.jsx)(o.code,{children:"import &#x7B; useAuth &#x7D; from '@/hooks/useAuth'"}),"?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": El barrel export (",(0,n.jsx)(o.code,{children:"hooks/index.ts"})," que re-exporta todos los hooks) ofrece DX conveniente (un solo import path). Pero tiene un costo: si no est\xe1 configurado correctamente, el bundler no puede tree-shake hooks no usados (porque el barrel file importa todo, creando dependencias laterales). Con ",(0,n.jsx)(o.code,{children:"import &#x7B; useAuth &#x7D; from '@/hooks/useAuth'"}),", el bundler solo carga ese archivo. La soluci\xf3n moderna: usar barrel exports condicionales con ",(0,n.jsx)(o.code,{children:"sideEffects: false"})," en ",(0,n.jsx)(o.code,{children:"package.json"})," o usar el flag ",(0,n.jsx)(o.code,{children:"importsNotUsedAsValues"})," de TypeScript para que los tipos no generen imports runtime."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": Vite/Rollup pueden tree-shake barrels si el m\xf3dulo es ESM y tiene ",(0,n.jsx)(o.code,{children:"sideEffects: false"}),". Pero si un hook tiene un side effect a nivel m\xf3dulo (como ",(0,n.jsx)(o.code,{children:"createContext"})," o instanciar un ",(0,n.jsx)(o.code,{children:"QueryClient"}),'), el barrel puede incluir ese side effect incluso si el hook no se usa. La mejor pr\xe1ctica actual (2026): evit\xe1 barrels para c\xf3digo que se comparte entre m\xfaltiples entry points (como una librer\xeda). Para una app como TaskFlow, el impacto es m\xednimo porque el bundle final incluye todo de todas formas. Pero es buena pr\xe1ctica mantener imports directos para m\xe1xima tree-shakeability. Fuente: "Barrel files and tree-shaking" en el blog de Marvin Hagemeister, "The Barrel File Debate" en twitter de desarrolladores de Vite, y la documentaci\xf3n de Rollup sobre tree-shaking.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"8-cuestionar-cu\xe1ndo-un-custom-hook-es-demasiado-abstracto-la-comunidad-debate-si-hooks-como-usewindowsize-useismounted-useprevious-son-genuinamente-\xfatiles-o-sobre-ingenier\xeda-1-3-l\xedneas-de-c\xf3digo-propio-vs-una-abstracci\xf3n-d\xf3nde-est\xe1-la-l\xednea-entre-hook-\xfatil-y-hook-innecesario",children:['8. [Cuestionar] \xbfCu\xe1ndo un custom hook es "demasiado" abstracto? La comunidad debate si hooks como ',(0,n.jsx)(o.code,{children:"useWindowSize"}),", ",(0,n.jsx)(o.code,{children:"useIsMounted"}),", ",(0,n.jsx)(o.code,{children:"usePrevious"}),' son genuinamente \xfatiles o sobre-ingenier\xeda (1-3 l\xedneas de c\xf3digo propio vs una abstracci\xf3n). \xbfD\xf3nde est\xe1 la l\xednea entre "hook \xfatil" y "hook innecesario"?']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": La l\xednea es: si el hook encapsula una API del navegador o l\xf3gica con cleanup (",(0,n.jsx)(o.code,{children:"useEventListener"}),", ",(0,n.jsx)(o.code,{children:"useMediaQuery"}),", ",(0,n.jsx)(o.code,{children:"useDebounce"}),"), es \xfatil porque abstrae complejidad (especialmente el cleanup que es f\xe1cil de olvidar). Si el hook es solo una o dos l\xedneas de React puro (",(0,n.jsx)(o.code,{children:"usePrevious"}),", ",(0,n.jsx)(o.code,{children:"useIsMounted"}),'), puede ser sobre-ingenier\xeda \u2014 el c\xf3digo inline es m\xe1s legible y directo. Kent C. Dodds argumenta que los hooks deben encapsular "comportamiento reutilizable con ciclo de vida", no "una l\xednea de state".']}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": ",(0,n.jsx)(o.code,{children:"usePrevious"})," es literalmente:"]}),"\n",(0,n.jsx)(o.pre,{children:(0,n.jsx)(o.code,{className:"language-ts",children:"function usePrevious<T>(value: T) {\r\n  const ref = useRef<T>()\r\n  useEffect(() => { ref.current = value })\r\n  return ref.current\r\n}\n"})}),"\n",(0,n.jsxs)(o.p,{children:["Son 4 l\xedneas. Crear un hook para esto agrega indirecci\xf3n sin reducir complejidad. ",(0,n.jsx)(o.code,{children:"useIsMounted()"})," es incluso peor porque es un patr\xf3n que generalmente indica un problema de dise\xf1o (deber\xedas cancelar el efecto, no verificar si est\xe1 montado). En contraste, ",(0,n.jsx)(o.code,{children:"useDebounce"})," encapsula ",(0,n.jsx)(o.code,{children:"useState"})," + ",(0,n.jsx)(o.code,{children:"useEffect"})," + ",(0,n.jsx)(o.code,{children:"setTimeout"})," + ",(0,n.jsx)(o.code,{children:"clearTimeout"}),' \u2014 10+ l\xedneas con l\xf3gica de timing y cleanup que es f\xe1cil de hacer mal. La pregunta a hacerse: "\xbfEste hook reduce la probabilidad de bugs?" Si la respuesta es s\xed, es un buen hook. Si solo ahorra 2 l\xedneas, probablemente no. Fuente: "When to create a custom hook" en el blog de Kent C. Dodds, "AHA Programming" (Avoid Hasty Abstractions) por Kent C. Dodds, y discusiones en reddit.com/r/reactjs.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsx)(o.h3,{id:"9-cuestionar-es-hooks-for-everything-una-buena-arquitectura-algunos-desarrolladores-crean-hooks-para-todo-useformvalidation-usetaskfiltering-usetasksorting-fragmentando-la-l\xf3gica-en-decenas-de-hooks-cu\xe1ndo-un-custom-hook-crea-m\xe1s-problemas-que-los-que-resuelve-prop-drilling-de-hooks-acoplamiento-oculto",children:'9. [Cuestionar] \xbfEs "hooks for everything" una buena arquitectura? Algunos desarrolladores crean hooks para TODO (useFormValidation, useTaskFiltering, useTaskSorting), fragmentando la l\xf3gica en decenas de hooks. \xbfCu\xe1ndo un custom hook crea m\xe1s problemas que los que resuelve (prop drilling de hooks, acoplamiento oculto)?'}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),': "Hooks for everything" es un antipatr\xf3n cuando los hooks no son reutilizables y solo sirven para extraer c\xf3digo de un componente a otro archivo. Si un hook ',(0,n.jsx)(o.code,{children:"useTaskForm"})," solo se usa en ",(0,n.jsx)(o.code,{children:"TaskForm.tsx"}),", no es un hook \u2014 es c\xf3digo que moviste de lugar sin beneficio. Los hooks deben ser reutilizables o encapsular comportamiento con ciclo de vida complejo. El acoplamiento oculto ocurre cuando m\xfaltiples hooks leen/escriben el mismo estado impl\xedcitamente (ej: un hook lee ",(0,n.jsx)(o.code,{children:"filter"})," de Context, otro hook llama a ",(0,n.jsx)(o.code,{children:"setFilter"})," via dispatch, y no hay una relaci\xf3n expl\xedcita entre ellos)."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": El problema no son los hooks en s\xed, sino la granularidad incorrecta. La soluci\xf3n es: (1) hooks por dominio, no por operaci\xf3n (",(0,n.jsx)(o.code,{children:"useTasks()"})," en lugar de ",(0,n.jsx)(o.code,{children:"useTaskFilter()"})," + ",(0,n.jsx)(o.code,{children:"useTaskSort()"})," + ",(0,n.jsx)(o.code,{children:"useTaskCreate()"}),'), (2) mantener la l\xf3gica cerca de donde se usa (si un hook solo se usa en un componente, inlinealo), (3) los hooks deben ser composables hacia arriba, no hacia los costados (un hook puede usar otros hooks, pero dos hooks hermanos no deber\xedan acoplarse impl\xedcitamente). Dan Abramov compar\xf3 esto con el problema de HOCs en 2017: "wrapper hell" se convirti\xf3 en "hook hell" cuando cada comportamiento es un hook separado. Fuente: "Why hooks are not a silver bullet" por Dan Abramov, "Custom hooks: When and why" en el blog de Tanner Linsley, y "Clean code with React hooks" por Kent C. Dodds.']}),"\n",(0,n.jsx)(o.hr,{}),"\n",(0,n.jsxs)(o.h3,{id:"10-cuestionar-la-clase-usa-useeffect-dentro-de-usedebounce-es-esto-correcto-o-deber\xeda-usar-uselayouteffect-la-comunidad-debate-cu\xe1ndo-usar-useeffect-vs-uselayouteffect-especialmente-en-hooks-de-ui-como-debounce-media-queries-y-resize-observers-qu\xe9-dice-el-equipo-de-react",children:["10. [Cuestionar] La clase usa ",(0,n.jsx)(o.code,{children:"useEffect"})," dentro de ",(0,n.jsx)(o.code,{children:"useDebounce"}),". \xbfEs esto correcto o deber\xeda usar ",(0,n.jsx)(o.code,{children:"useLayoutEffect"}),"? La comunidad debate cu\xe1ndo usar ",(0,n.jsx)(o.code,{children:"useEffect"})," vs ",(0,n.jsx)(o.code,{children:"useLayoutEffect"}),", especialmente en hooks de UI como debounce, media queries, y resize observers. \xbfQu\xe9 dice el equipo de React?"]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Respuesta"}),": Para ",(0,n.jsx)(o.code,{children:"useDebounce"}),", ",(0,n.jsx)(o.code,{children:"useEffect"})," es correcto porque no necesitamos leer/escribir el DOM sincr\xf3nicamente. ",(0,n.jsx)(o.code,{children:"useLayoutEffect"})," se usa cuando necesit\xe1s medir el DOM y aplicar cambios antes de que el navegador pinte (para evitar flickering). Para hooks de UI: ",(0,n.jsx)(o.code,{children:"useMediaQuery"})," (no modifica DOM) \u2192 ",(0,n.jsx)(o.code,{children:"useEffect"}),"; ",(0,n.jsx)(o.code,{children:"useResizeObserver"})," (mide DOM) \u2192 ",(0,n.jsx)(o.code,{children:"useLayoutEffect"})," para evitar CLS si el tama\xf1o afecta el layout; ",(0,n.jsx)(o.code,{children:"useDebounce"})," (solo l\xf3gica de timing) \u2192 ",(0,n.jsx)(o.code,{children:"useEffect"}),". La regla del equipo de React: empez\xe1 con ",(0,n.jsx)(o.code,{children:"useEffect"}),", solo cambi\xe1 a ",(0,n.jsx)(o.code,{children:"useLayoutEffect"})," si ves flickering visual o necesit\xe1s la medida del DOM antes del paint."]}),"\n",(0,n.jsxs)(o.p,{children:[(0,n.jsx)(o.strong,{children:"Por qu\xe9"}),": La diferencia pr\xe1ctica: ",(0,n.jsx)(o.code,{children:"useEffect"})," se ejecuta despu\xe9s de que el navegador pint\xf3 (el usuario ve el cambio, luego el efecto se ejecuta). ",(0,n.jsx)(o.code,{children:"useLayoutEffect"})," se ejecuta despu\xe9s del commit del DOM pero antes del paint (el navegador no ha pintado a\xfan). Si med\xeds el DOM en ",(0,n.jsx)(o.code,{children:"useEffect"})," y actualiz\xe1s estado basado en esa medida, el usuario ver\xe1 el layout viejo por un frame y luego el nuevo \u2014 flickering. Si lo hac\xe9s en ",(0,n.jsx)(o.code,{children:"useLayoutEffect"}),', el cambio se aplica antes del paint y el usuario nunca ve el estado intermedio. Fuente: "useEffect vs useLayoutEffect" en react.dev, "When to use useLayoutEffect" por Kent C. Dodds, y el art\xedculo "You might not need useLayoutEffect" por Dan Abramov.']})]})}function l(e={}){const{wrapper:o}={...(0,r.R)(),...e.components};return o?(0,n.jsx)(o,{...e,children:(0,n.jsx)(u,{...e})}):u(e)}},28453(e,o,s){s.d(o,{R:()=>t,x:()=>c});var a=s(96540);const n={},r=a.createContext(n);function t(e){const o=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function c(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:t(e.components),a.createElement(r.Provider,{value:o},e.children)}}}]);